<template><div><h1>Sites</h1><p>Document campuses and physical locations.</p><div class="panel"><h2>Add site</h2><form class="form" @submit.prevent="add"><label>Site name</label><input v-model="name" maxlength="120" required placeholder="Main Campus"><label>Address (optional)</label><input v-model="address" maxlength="300" placeholder="Street, suburb"><button class="btn" :disabled="saving || !isAdmin">{{ saving?'Saving…':'Add site' }}</button></form><p v-if="!isAdmin" class="muted">Only administrators can change records.</p></div><div class="panel"><h2>All sites</h2><p v-if="loading">Loading…</p><table v-else class="table"><thead><tr><th>Name</th><th>Address</th><th v-if="isAdmin">Actions</th></tr></thead><tbody><tr v-for="site in sites" :key="site.id"><td>{{site.name}}</td><td>{{site.address||'—'}}</td><td v-if="isAdmin"><button class="btn" @click="remove(site.id)">Delete</button></td></tr><tr v-if="!sites.length"><td colspan="3">No sites yet.</td></tr></tbody></table></div><p v-if="error" class="danger">{{error}}</p></div></template>
<script setup lang="ts">
definePageMeta({middleware:'auth'});const client=useSupabaseClient();const {isAdmin,refreshRole}=useAccess();const name=ref(''),address=ref(''),error=ref(''),saving=ref(false),loading=ref(true);const sites=ref<any[]>([])
async function load(){loading.value=true;const {data,error:e}=await client.from('sites').select('id,name,address').order('name');sites.value=data||[];error.value=e?.message||'';loading.value=false}
async function add(){saving.value=true;error.value='';const {error:e}=await client.from('sites').insert({name:name.value.trim(),address:address.value.trim()||null});if(e)error.value=e.message;else{name.value='';address.value='';await load()}saving.value=false}
async function remove(id:string){if(!confirm('Delete this site and its buildings?'))return;const {error:e}=await client.from('sites').delete().eq('id',id);if(e)error.value=e.message;else await load()}
onMounted(async()=>{try{await refreshRole();await load()}catch(e:any){error.value=e.message}})
</script>
